28	/// A single test.
29	pub struct Test {
30	    pub name: EcoString,
31	    pub attrs: Attrs,
32	    pub body: TestBody,
33	}
34	
35	impl Test {
36	    /// Whether this test output should be compared and saved, this is true for
37	    /// stages that are explicitly specified and those that are
38	    /// [implied](TestStages::with_implied).
39	    pub fn should_check(&self, output: TestOutput) -> bool {
40	        ARGS.required_stages()
41	            .intersects(self.attrs.implied_stages() & output.into())
42	    }
43	
44	    /// Whether this test stage should be run, test stages that are
45	    /// [required](TestStages::with_required) by another stage mus be run, even
46	    /// if they aren't explicitly specified.
47	    pub fn should_run(&self, stage: impl TestStage) -> bool {
48	        ARGS.required_stages()
49	            .intersects(self.attrs.implied_stages().with_required() & stage.into())
50	    }
51	}
52	
53	impl Display for Test {
54	    fn fmt(&self, f: &mut Formatter) -> fmt::Result {
55	        // underline path
56	        if std::io::stdout().is_terminal() {
57	            write!(f, "{} (\x1B[4m{}\x1B[0m)", self.name, self.body.pos)
58	        } else {
59	            write!(f, "{} ({})", self.name, self.body.pos)
