130	    ///
131	    /// Here's a visual representation of the stage tree:
132	    /// ```txt
133	    ///                  ╭─> render
134	    ///       ╭─> paged ─┼─> pdf ───> pdftags
135	    /// eval ─┤          ╰─> svg
136	    ///       ├─> html -───> html
137	    ///       ╰─> bundle ──> bundle
138	    /// ```
139	    #[derive(Debug, Default, Copy, Clone, Eq, PartialEq)]
140	    pub struct TestStages: u8 {
141	        const EVAL = 1 << 0;
142	        const PAGED = 1 << 1;
143	        const RENDER = 1 << 2;
144	        const PDF = 1 << 3;
145	        const PDFTAGS = 1 << 4;
146	        const SVG = 1 << 5;
147	        const HTML = 1 << 6;
