                "paged" => self.set_attr(attr_name, &mut stages, TestStages::PAGED),
                "pdf" => self.set_attr(attr_name, &mut stages, TestStages::PDF),
                "pdftags" => self.set_attr(attr_name, &mut stages, TestStages::PDFTAGS),
