//! Test sources and error/warning annotations in tests.
//!
//! Note that as of Feb 2025, there are only around 1400 annotations total in
//! the test suite, so optimizations here should be for developer comfort, not
//! size/speed.
use std::fmt::{self, Display, Formatter, Write};
use std::ops::Range;
use std::path::Path;
use std::sync::LazyLock;

use regex::{Captures, Regex};
use typst::diag::{StrResult, bail};
use typst::foundations::Bytes;
use typst::{World, WorldExt as _};
use typst_kit::files::FileLoader as _;
use typst_syntax::package::PackageVersion;
use typst_syntax::{
    DiagSpan, DiagSpanKind, FileId, Lines, RootedPath, Source, VirtualPath, VirtualRoot,
};
use unscanny::Scanner;

use crate::collect::{Attrs, FilePos, TestParseError, TestStages};
use crate::world::{TestFiles, TestWorld};

/// The body of a test.
pub struct TestBody {
    /// The start of the body.
    pub pos: FilePos,
    /// The source of the body, excluding annotation comments.
    pub source: Source,
    /// The annotation comments for this test.
    pub notes: Vec<Note>,
}

impl TestBody {
    /// Whether there are any annotated errors.
    pub fn has_error(&self) -> bool {
        self.notes.iter().any(|n| n.kind == NoteKind::Error)
    }

    /// Search for a matching note to mark as seen, or update the notes vector
    /// by changing a close match or appending a new emitted note.
    pub fn mark_seen_or_update(
        &mut self,
        Note { status, seen, kind, range, message }: Note,
    ) {
        let mut best = None;
        let mut range_message_lines_cols = [false; 4];
        for (i, note) in self.notes.iter_mut().enumerate() {
            // Only consider notes that haven't been seen yet.
            if note.seen.contains(seen) {
                continue;
            }
            let same_range = note.range == range;
            let same_message = note.message == message;

            // If kind differs, we skip unless both range and message match.
            if note.kind != kind {
                if same_range
                    && same_message
                    && let NoteStatus::Annotated { pos } = &note.status
                {
                    best = Some((i, pos.clone()));
                    break;
                }
            } else if same_range && same_message {
                // A perfect match! Mark as seen and return.
                note.seen |= seen;
                return;
            } else if let NoteStatus::Annotated { pos } = &note.status
                && note.seen.is_empty()
            {
                // Order the other possible matches by comparing the range, then
                // message, then single lines, then columns. If none match exactly,
                // treat as not emitted.
                let same_r_m_l_c = [
                    same_range,
                    same_message,
                    note.range.single_line() == range.single_line(),
                    note.range.columns() == range.columns(),
                ];
                if same_r_m_l_c > range_message_lines_cols {
                    best = Some((i, pos.clone()));
                    range_message_lines_cols = same_r_m_l_c;
                }
            }
        }
        match best {
            Some((i, pos)) => {
                let note = &mut self.notes[i];
                note.seen |= seen;
                // We replace the note's kind/range/message (which should cause
                // it to match exactly in future stages), but keep the old
                // values to report the difference.
                let annotated = Box::new((
                    std::mem::replace(&mut note.kind, kind),
                    std::mem::replace(&mut note.range, range),
                    std::mem::replace(&mut note.message, message),
                ));
                note.status = NoteStatus::Updated { pos, annotated };
            }
            None => self.notes.push(Note { status, seen, kind, range, message }),
        }
    }

    /// Create a new body for this test with only the seen annotations.
    pub fn write_seen_annotations(&mut self) -> (String, [(&'static str, usize); 3]) {
        let old = self.source.text();
        let mut new = String::with_capacity(old.len());
        let mut lines = old.lines().enumerate().peekable();

        // Stable sort keeps Warning/Error annotations well-ordered relative to
        // their Hints since hints usually have the same range.
        self.notes.sort_by_key(|note| match &note.range {
            // Compare by None < Some, external < internal, start-A < start-B,
            // then end-A < end-B.
            // Assume external notes are all for the same file (currently true).
            NoteRange::None => None, // Option::None < Option::Some
            NoteRange::Some { external_file, indices, .. } => {
                Some((external_file.is_none(), indices.start, indices.end))
            }
        });

        let (mut removed, mut added, mut adjusted) = (0, 0, 0);
        for Note { kind, range, message, status, seen } in &self.notes {
            match status {
                NoteStatus::Annotated { .. } if seen.is_empty() => {
                    removed += 1;
                    continue;
                }
                NoteStatus::Annotated { .. } => {}
                NoteStatus::Updated { .. } => adjusted += 1,
                NoteStatus::Emitted => added += 1,
            }
            match &range {
                NoteRange::None => {
                    writeln!(new, "// {kind}: {message}").unwrap();
                }
                NoteRange::Some { external_file: Some(_), .. } => {
                    // Don't compare external line numbers to test lines.
                    writeln!(new, "// {kind}: {range} {message}").unwrap();
                }
                NoteRange::Some { positions: Range { start, .. }, .. } => {
                    while let Some(&(line_index, line)) = lines.peek()
                        && line_index < start.line
                    {
                        new.push_str(line);
                        new.push('\n');
                        lines.next();
                    }
                    // Indent the same as the line being annotated.
                    if let Some(&(_, line)) = lines.peek() {
                        new.push_str(Scanner::new(line).eat_while(' '));
                    }
                    // Write line numbers relative to the annotated line, not
                    // relative to the start of the test.
                    let relative_range = range.clone().with_relative_start_line();
                    writeln!(new, "// {kind}: {relative_range} {message}").unwrap();
                }
            }
        }
        for (_, line) in lines {
            new.push_str(line);
            new.push('\n');
        }

        let stats = [("removed", removed), ("added", added), ("adjusted", adjusted)];
        (new, stats)
    }
}

/// An annotation like `// Error: 2-6 message` in a test.
pub struct Note {
    pub status: NoteStatus,
    pub seen: TestStages,
    pub kind: NoteKind,
    pub range: NoteRange,
    pub message: String,
}

/// The status of an annotated diagnostic.
pub enum NoteStatus {
    /// An annotated note that has only seen perfect matches.
    Annotated { pos: FilePos },
    /// An annotated note that saw a close match and has been updated. Retains
    /// its orginal kind, range, and message.
    Updated { pos: FilePos, annotated: Box<(NoteKind, NoteRange, String)> },
    /// An emitted note that was not annotated.
    Emitted,
}

/// A kind of annotation in a test.
#[derive(Debug, Copy, Clone, Eq, PartialEq)]
pub enum NoteKind {
    Error,
    Warning,
    Hint,
    Trace,
}

impl Display for NoteKind {
    fn fmt(&self, f: &mut Formatter) -> fmt::Result {
        f.pad(match self {
            Self::Error => "Error",
            Self::Warning => "Warning",
            Self::Hint => "Hint",
            Self::Trace => "Trace",
        })
    }
}

impl Note {
    /// Build a new emitted note from a span and world.
    pub fn emitted(
        kind: NoteKind,
        stage: TestStages,
        message: impl Into<String>,
        span: DiagSpan,
        world: &TestWorld,
    ) -> Self {
        let range = if let Some(file) = span.id()
            && let Some(indices) = world.range(span)
        {
            // We don't call `.source()` because file may not be Typst code.
            let lines = world.file(file).unwrap().lines().unwrap();
            let start = LineCol::from_index(indices.start, &lines).unwrap();
            let end = LineCol::from_index(indices.end, &lines).unwrap();
            NoteRange::Some {
                lines,
                external_file: (file != world.main()).then_some(file),
                indices,
                positions: start..end,
            }
        } else {
            assert!(matches!(span.get(), DiagSpanKind::Detached));
            NoteRange::None
        };

        let mut message = message.into();
        if message.contains('\\') {
            // HACK: Replace backslashes in path sepators with slashes for cross
            // platform reproducible error messages.
            static RE: LazyLock<Regex> =
                LazyLock::new(|| Regex::new("\\((.*) (at|in) (.+)\\)").unwrap());
            message = RE
                .replace(&message, |caps: &Captures| {
                    let path = caps[3].replace('\\', "/");
                    format!("({} {} {})", &caps[1], &caps[2], path)
                })
                .into();
        }

        Self {
            status: NoteStatus::Emitted,
            seen: stage,
            kind,
            range,
            // Annotated messages must be a single line.
            message: message.replace("\n", "\\n"),
        }

use std::cell::OnceCell;
use std::path::PathBuf;

use clap::{Parser, Subcommand, ValueEnum};
use regex::Regex;

use crate::collect::TestStages;

/// Typst's test runner.
#[derive(Debug, Clone, Parser)]
#[command(bin_name = "cargo testit")]
#[clap(name = "typst-test", author)]
pub struct CliArguments {
    /// The command to run.
    #[command(subcommand)]
    pub command: Option<Command>,
    /// All the tests whose names match the test name pattern will be run.
    #[arg(value_parser = Regex::new)]
    pub pattern: Vec<Regex>,
    /// Restricts test selection within the given path.
    #[arg(short, long, value_parser = |s: &str| PathBuf::from(s).canonicalize())]
    pub path: Vec<PathBuf>,
    /// Only selects the test that matches with the test name verbatim.
    #[arg(short, long)]
    pub exact: bool,
    /// Lists what tests will be run, without actually running them.
    #[arg(long, group = "action")]
    pub list: bool,
    /// Updates the reference output of non-passing tests.
    #[arg(short, long, group = "action")]
    pub update: bool,
    /// Specify which test targets/outputs to run.
    ///
    /// This is useful to only update specific reference outputs of a test.
    #[arg(long, value_delimiter = ',')]
    pub stages: Vec<TestStage>,
    /// The scaling factor to render the output image with.
    ///
    /// Does not affect the comparison or the reference image.
    #[arg(short, long, default_value_t = 1.0)]
    pub scale: f64,
    /// Displays the syntax tree before running tests.
    ///
    /// Note: This is ignored if using '--syntax-compare'.
    #[arg(long)]
    pub syntax: bool,
    /// Displays only one line per test, hiding details about failures.
    #[arg(short, long)]
    pub compact: bool,
    /// Prevents the terminal from being cleared of test names.
    #[arg(short, long)]
    pub verbose: bool,
    /// How many threads to spawn when running the tests.
    #[arg(short = 'j', long)]
    pub num_threads: Option<usize>,
    /// Open the generated HTML test report in a browser when finished.
    #[arg(long)]
    pub open_report: bool,
    /// Don't generate a HTML test report.
    #[arg(long)]
    no_report: bool,
    /// The git base revision against which the tests will be run.
    ///
    /// If none is specified, it's compared against the current working tree.
    #[arg(long, conflicts_with = "update")]
    pub base_revision: Option<String>,
    /// Print errors in a format that github actions can pick up to generate
    /// annotations that will be displayed on PR files:
    /// <https://docs.github.com/en/actions/reference/workflows-and-actions/workflow-commands#setting-an-error-message>
    #[arg(long, env = "USE_GITHUB_ANNOTATIONS")]
    pub use_github_annotations: bool,
    /// Changes testing behavior for debugging the parser: With no argument,
    /// outputs the concrete syntax trees of tests as files in
    /// 'tests/store/syntax/'. With a directory as argument, will treat it as a
    /// reference of correct syntax tree files and will print which output
    /// syntax trees differ (viewing the diffs is on you).
    ///
    /// This overrides the normal testing system. It parses, but does not run
    /// the test suite.
    ///
    /// If `cargo test` is run with `--no-default-features`, then compiling will
    /// not include Typst's core crates, only typst-syntax, greatly speeding up
    /// debugging when changing the parser.
    ///
    /// You can generate a correct reference directory by running on a known
    /// good commit and copying the generated outputs to a new directory.
    /// `_things` may be a good location as it is in the top-level gitignore.
    ///
    /// You can view diffs in VS Code with: `code --diff <ref_dir>/<test>.syntax
    /// tests/store/syntax/<test>.syntax`
    #[arg(long)]
    pub parser_compare: Option<Option<PathBuf>>,
    // ^ I'm not using a subcommand here because then test patterns don't parse
    // how you would expect and I'm too lazy to try to fix it.
}

impl CliArguments {
    /// The stages which should be run depending on the `--stages` flag.
    fn stages(&self) -> TestStages {
        thread_local! {
            static CACHED: OnceCell<TestStages> = const { OnceCell::new() };
        }

        CACHED.with(|cell| {
            *cell.get_or_init(|| {
                if self.stages.is_empty() {
                    TestStages::all()
                } else {
                    let mut stages = TestStages::empty();
                    for &s in &self.stages {
                        stages |= s.into();
                    }
                    stages
                }
            })
        })
    }

    /// The stages that were parsed and the ones that are implied.
    pub fn implied_stages(&self) -> TestStages {
        self.stages().with_implied()
    }

    /// [`Self::implied_stages`] and the ones that are required.
    pub fn required_stages(&self) -> TestStages {
        // Must be in this order, otherwise any paged output target
        // would enable all others.
        self.stages().with_implied().with_required()
    }

    /// Whether a HTML test report should be generated.
    pub fn gen_report(&self) -> bool {
        !self.no_report && !self.update
    }
}

/// What to do.
#[derive(Debug, Clone, Subcommand)]
#[command()]
pub enum Command {
    /// Clears the on-disk test artifact store.
    Clean,
    /// Deletes all dangling reference output.
    Undangle,
    /// Prints the tags from a PDF file.
    Pdftags(PdftagsCommand),
    /// Open the last generated HTML test report in a browser.
    OpenReport,
}

