58	    let mut cmd = RegenCommand::default();
59	    while let Some(arg) = args.next() {
60	        if let Some(val) = parse_arg_value(&arg, &mut args, "base-revision") {
61	            cmd.base_revision = Some(val);
62	        } else if arg == "--rerun" {
